#!/usr/bin/env bash
# Supplementary campaign passes for the dual algorithms DFMA and DHFMA
# (docs/PIANO_PARTE_COMPUTAZIONALE.md section 3: DFMA is the general dual of
# FMA, DHFMA the general dual of HFMA). They are already covered by the
# correctness/differential suite in tests/test_main.cpp; this script adds
# them to the same official campaign instance sets used for FMA/HFMA/RaC
# timing, reusing the instances already generated by
# tools/run_official_campaigns.sh (no regeneration). DFMA shares FMA's
# O(n^2)-ish scaling (empirically confirmed: ~22s at n=20000, matching FMA),
# so it is scoped to the same size cutoff as FMA; DHFMA is heap-based like
# HFMA and is run at full scale, still under the same timeout/memory guard.
#
# Runs on a separate CPU core from tools/run_official_campaigns.sh so both
# can proceed concurrently without contention.
set -euo pipefail
cd "$(dirname "$0")/.."

BIN=build/pcf_benchmark
RUN="python3 tools/run_benchmark.py"
MEM_LIMIT_KIB=8000000
TIMEOUT_S=300
CORE=1
TASKSET=""
if command -v taskset >/dev/null 2>&1; then TASKSET="taskset -c ${CORE}"; fi

run() {
  local dir=$1 algs=$2 reps=$3 cid=$4 seed=$5
  local out=results/raw/${cid}_${algs//,/-}.csv
  echo "=== ${cid} :: ${algs} (${reps} reps) on ${dir} -> ${out} ==="
  ${TASKSET} ${RUN} --binary "${BIN}" --instances "${dir}" --output "${out}" \
    --algorithms "${algs}" --repetitions "${reps}" --campaign-id "${cid}" \
    --shuffle-seed "${seed}" --timeout-seconds "${TIMEOUT_S}" --memory-limit-kib "${MEM_LIMIT_KIB}"
}

wait_for_dir() {
  local dir=$1
  while [ ! -d "${dir}" ]; do
    echo "waiting for ${dir} to be generated by run_official_campaigns.sh..."
    sleep 30
  done
}

campaign_b()  { run instances/campaign_b dfma,dhfma 11 campaign_b 5; }

campaign_c()  {
  run instances/campaign_c dhfma 3 campaign_c 6
  run instances/campaign_c_fma_subset dfma 2 campaign_c 6
}

campaign_d()  {
  for shape in path binary star; do
    wait_for_dir "instances/campaign_d_${shape}"
    run "instances/campaign_d_${shape}" dhfma 3 "campaign_d_${shape}" 7
    run "instances/campaign_d_${shape}_fma_subset" dfma 3 "campaign_d_${shape}" 7
  done
}

campaign_e() {
  for topo in in out; do
    wait_for_dir "instances/campaign_e_${topo}"
    run "instances/campaign_e_${topo}" dhfma 3 "campaign_e_${topo}" 8
  done
}

mkdir -p results/raw
targets=("$@")
[ ${#targets[@]} -eq 0 ] && targets=(b c d e)
for target in "${targets[@]}"; do
  "campaign_${target}"
done
echo "=== dual-variant campaigns finished: $(date -u +%FT%TZ) ==="
